<script setup lang="ts">/** * architecture-3.vue � Ruang Studio * Interior studio. Fraunces italic H1, Inter body, JetBrains Mono metadata. * 8 sections: Hero+3D, Layanan, Proyek, Material, Quiz, Galeri, Kontak, Footer * Palette: ruang (light, terracotta accent) * Typography: ruang (Fraunces italic + Inter + JetBrains Mono) */import { ref, computed, reactive } from 'vue'import { toCss } from '~/utils/palettes'definePageMeta({ layout: false })const theme = useTemplateTheme('architecture-3')const { tpl, styles, h1Style, h2Style, monoStyle, palette } = themeuseScrollReveal('architecture-3')const accentCss = toCss(palette.accent)const accentSoftCss = toCss(palette.accentSoft)const fgCss = toCss(palette.fg)const bgCss = toCss(palette.bg)const surfaceCss = toCss(palette.surface)const surfaceElevatedCss = toCss(palette.surfaceElevated)const mutedCss = toCss(palette.muted)const borderCss = toCss(palette.border)const accentFgCss = toCss(palette.accentFg)// ============================================================// STATE// ============================================================const heroLoaded = ref(false)const lightboxOpen = ref(false)const lightboxIndex = ref(0)// Quiz stateconst quizStep = ref(0)const quizAnswers = ref<number[]>([])const quizDone = ref(false)onMounted(() => { setTimeout(() => { heroLoaded.value = true }, 150) })// ============================================================// DATA � Layanan// ============================================================const layanan = [  { icon: 'i-lucide-pen-tool', title: 'Desain Interior', desc: 'Konsep hingga penataan akhir. Moodboard, denah, dan rencana pencahayaan.' },  { icon: 'i-lucide-message-circle', title: 'Konsultasi', desc: 'Sesi 60 menit. Analisis ruangan, rekomendasi gaya, estimasi anggaran.' },  { icon: 'i-lucide-paintbrush', title: 'Styling', desc: 'Aksesori, tanaman, tekstil. Ruangan langsung siap ditempati.' },  { icon: 'i-lucide-cube', title: 'Visualisasi', desc: 'Render 3D fotorealistik sebelum eksekusi. Lihat sebelum belanja.' },]// ============================================================// DATA � Proyek// ============================================================const proyek = [  { name: 'Ruang Kerja Minimalis', style: 'Minimalis', location: 'Jakarta Selatan', year: '2025', desc: 'Kantor 18 m\u00B2 dengan meja jati custom dan rak tersembunyi. Cahaya alami penuh tanpa lampu siang hari.' },  { name: 'Apartemen Studio', style: 'Skandinavia', location: 'Bandung', year: '2024', desc: 'Unit 28 m\u00B2 yang terasa lapang berkat palet terang dan furnitur multifungsi. Dapur terbuka menyatu.' },  { name: 'Rumah Keluarga', style: 'Klasik', location: 'BSD City', year: '2024', desc: 'Tiga kamar dengan ruang bermain anak terintegrasi. Material lokal: batu palimanan dan kayu jati.' },  { name: 'Kafe Industrial', style: 'Industrial', location: 'Bandung', year: '2023', desc: 'Kafe 85 m\u00B2 dengan bata ekspos, besi tempa, dan lampu Edison. Hangat meski industrial.' },  { name: 'Butik Fashion', style: 'Boho', location: 'Kemang, Jakarta', year: '2023', desc: 'Butik 45 m\u00B2 dengan rotan anyaman, cermin lengkung, dan lantai teraso. Setiap sudut spot foto.' },  { name: 'Villa Pantai', style: 'Boho', location: 'Canggu, Bali', year: '2025', desc: 'Pintu geser kaca membuka ke taman tropis. Kayu kelapa, linen putih, anyaman bambu lokal.' },]// ============================================================// DATA � Material (6 Indonesian materials)// ============================================================const materials = [  { name: 'Jati Jepara', origin: 'Jepara, Jawa Tengah', desc: 'Kayu jati reclaimed dari perahu nelayan. Serat unik, tahan rayap, makin indah seiring waktu.', color: '#8B6914', category: 'Kayu' },  { name: 'Linen', origin: 'Eropa (via Jakarta)', desc: 'Kain natural untuk tirai dan tekstil. Lembut, bernapas, makin lentur setelah dicuci.', color: '#D4C5A9', category: 'Tekstil' },  { name: 'Palimanan', origin: 'Cirebon, Jawa Barat', desc: 'Batu kapur krem kekuningan. Cocok untuk dinding aksen dan lantai teras. Terjangkau.', color: '#E8D5B7', category: 'Batu' },  { name: 'Kuningan', origin: 'Yogyakarta', desc: 'Logam paten alami untuk pegangan pintu dan lampu gantung. Berubah emas ke cokelat gelap.', color: '#B8860B', category: 'Logam' },  { name: 'Keramik', origin: 'Plered, Jawa Barat', desc: 'Keramik tangan dengan glazur tak rata. Setiap keping unik, hidupkan dinding dapur.', color: '#C4A882', category: 'Keramik' },  { name: 'Batu Alam', origin: 'Bali & Lombok', desc: 'Batu kali dan paras untuk taman dan kamar mandi. Tahan cuaca, tekstur alami.', color: '#9B8B7A', category: 'Batu' },]// ============================================================// DATA � Quiz (5 questions, 4 options each)// ============================================================const quizQuestions = [  { q: 'Perasaan pertama saat masuk ruangan ideal?', options: ['Tenang dan rapi', 'Hangat dan penuh karakter', 'Megah dan elegan', 'Bebas dan penuh warna'] },  { q: 'Warna yang paling membuat nyaman?', options: ['Putih, krem, abu terang', 'Cokelat kayu, hijau zaitun', 'Hitam, emas, marmer gelap', 'Terracotta, mustard, sage'] },  { q: 'Material yang disentuh duluan di toko furnitur?', options: ['Kayu berwarna terang', 'Kayu jati tua atau batu alam', 'Marmer atau logam mengkilap', 'Rotan, linen, anyaman'] },  { q: 'Suasana saat pulang kerja?', options: ['Hotel yang rapi dan tenang', 'Rumah nenek yang hangat', 'Lobi hotel bintang lima', 'Kafe di Bali yang santai'] },  { q: 'Anggaran untuk satu ruangan?', options: ['Di bawah Rp 50 juta', 'Rp 50 - 150 juta', 'Rp 150 - 300 juta', 'Di atas Rp 300 juta'] },]const quizStyles = ['Minimalis', 'Klasik', 'Industrial', 'Boho']const quizStyleDescriptions: Record<string, string> = {  Minimalis: 'Bersih, fungsional, tidak berlebihan. Sedikit elemen, dampak besar.',  Klasik: 'Kemewahan yang tidak mencolok. Material pilihan, detail halus.',  Industrial: 'Kejujuran material. Bata ekspos, besi tempa, beton polos.',  Boho: 'Tekstur, pola, dan tanaman. Ruangan hidup dan personal.',}const quizResult = computed(() => {  if (!quizDone.value) return null  const counts = [0, 0, 0, 0]  quizAnswers.value.forEach((a) => { counts[a]++ })  const maxIdx = counts.indexOf(Math.max(...counts))  const style = quizStyles[maxIdx]  return { style, desc: quizStyleDescriptions[style] }})function answerQuiz(optionIdx: number) {  quizAnswers.value.push(optionIdx)  if (quizStep.value < quizQuestions.length - 1) {    quizStep.value++  } else {    quizDone.value = true  }}function resetQuiz() {  quizStep.value = 0  quizAnswers.value = []  quizDone.value = false}// ============================================================// DATA � Galeri (8 photos)// ============================================================const galeri = [  { label: 'Ruang Tamu', angle: 15 },  { label: 'Dapur', angle: 45 },  { label: 'Kamar Tidur', angle: 75 },  { label: 'Kamar Mandi', angle: 105 },  { label: 'Ruang Kerja', angle: 135 },  { label: 'Teras', angle: 165 },  { label: 'Ruang Makan', angle: 195 },  { label: 'Taman Dalam', angle: 225 },]// ============================================================// DATA � Sample box// ============================================================const sampleBoxOpen = ref(false)// ============================================================// HELPERS// ============================================================const waUrl = computed(() => {  const msg = 'Halo Ruang Studio, saya tertarik untuk memulai proyek interior. Bisa diskusi?'  return 'https://wa.me/6285188627365?text=' + encodeURIComponent(msg)})</script><template>  <div    :style="{      ...styles,      '--ruang-accent': accentCss,      '--ruang-accent-soft': accentSoftCss,      '--ruang-accent-fg': accentFgCss,    }"  >    <TmplBack />    <!-- ===== NAV ===== -->    <TmplNavbar      brand="Ruang Studio"      :links="[        { label: 'Layanan', href: '#layanan' },        { label: 'Proyek', href: '#proyek' },        { label: 'Material', href: '#material' },        { label: 'Kuis', href: '#kuis' },        { label: 'Galeri', href: '#galeri' },        { label: 'Kontak', href: '#kontak' },      ]"      :accent="accentCss"      :bg="surfaceElevatedCss"      :text="fgCss"      variant="glass"      :show-theme-toggle="false"      :show-whatsapp-cta="true"      whatsapp-message="Halo Ruang Studio, saya mau tanya soal desain interior."    />    <!-- ===== SECTION 1: HERO + 3D ===== -->    <section id="hero" class="ruang-hero" data-section :style="{ 'view-transition-name': 'hero-architecture-3'" }>      <div class="ruang-hero__inner">        <div class="ruang-hero__text">          <Transition appear enter-active-class="transition-all duration-1000 ease-out" enter-from-class="opacity-0 translate-y-6" enter-to-class="opacity-100 translate-y-0">            <div v-if="heroLoaded">              <p class="ruang-hero__label" :style="monoStyle">Studio Desain Interior &middot; Jakarta &amp; Bandung</p>              <h1 :style="h1Style" class="ruang-hero__title">Ruang yang<br>bercerita.</h1>              <p class="ruang-hero__sub">Interior untuk apartemen, rumah, dan ruang kerja. 6 gaya, 1 filosofi: ruangan yang terasa personal.</p>              <div class="ruang-hero__ctas">                <a href="#kuis" class="ruang-btn ruang-btn--primary" :style="{ background: accentCss, color: accentFgCss }">Temukan Gaya Anda</a>                <a href="#proyek" class="ruang-btn ruang-btn--ghost" :style="{ borderColor: accentCss, color: accentCss }">Lihat Proyek</a>              </div>            </div>          </Transition>        </div>        <!-- 3D Material Sphere placeholder -->        <div class="ruang-hero__sphere-wrap">          <div class="ruang-hero__sphere">            <div              v-for="(m, i) in materials"              :key="m.name"              class="ruang-hero__sphere-petal"              :style="{                background: m.color,                transform: `rotate(${i * 60}deg) translateY(-100px)`,                animationDelay: `${i * 0.2}s`,              }"            />            <span class="ruang-hero__sphere-label" :style="monoStyle">Material Sphere</span>          </div>        </div>      </div>      <div class="ruang-hero__scroll" :style="monoStyle">Scroll</div>    </section>    <!-- ===== SECTION 2: LAYANAN ===== -->    <section id="layanan" class="ruang-section" data-section>      <div class="ruang-container">        <p class="ruang-label" :style="monoStyle">Layanan</p>        <h2 :style="h2Style" class="ruang-h2">Empat cara kami membantu.</h2>        <div class="ruang-layanan-grid" data-reveal="stagger-children">          <article            v-for="(s, i) in layanan"            :key="s.title"            class="ruang-layanan-card"            :style="{ borderColor: borderCss }"          >            <div class="ruang-layanan-icon" :style="{ background: accentSoftCss, color: accentCss }">              <UIcon :name="s.icon" class="w-5 h-5" />            </div>            <span class="ruang-layanan-num" :style="monoStyle">0{{ i + 1 }}</span>            <h3 class="ruang-layanan-title">{{ s.title }}</h3>            <p class="ruang-layanan-desc">{{ s.desc }}</p>          </article>        </div>      </div>    </section>    <!-- ===== SECTION 3: PROYEK ===== -->    <section id="proyek" class="ruang-section ruang-section--alt" :style="{ background: surfaceCss }" data-section>      <div class="ruang-container">        <p class="ruang-label" :style="monoStyle">Proyek</p>        <h2 :style="h2Style" class="ruang-h2">Enam ruangan, enam cerita.</h2>        <div class="ruang-proyek-grid" data-reveal="stagger-children">          <article            v-for="(p, i) in proyek"            :key="p.name"            class="ruang-proyek-card"          >            <div              class="ruang-proyek-img"              :style="{                background: `linear-gradient(${135 + i * 30}deg, ${accentSoftCss}, ${mutedCss})`,              }"            >              <span class="ruang-proyek-img-label" :style="monoStyle">Foto interior</span>            </div>            <div class="ruang-proyek-info">              <div class="ruang-proyek-meta">                <span class="ruang-proyek-tag" :style="{ background: accentSoftCss, color: accentCss }">{{ p.style }}</span>                <span :style="monoStyle" class="ruang-proyek-loc">{{ p.location }}</span>              </div>              <h3 class="ruang-proyek-name">{{ p.name }}</h3>              <p class="ruang-proyek-desc">{{ p.desc }}</p>              <span :style="monoStyle" class="ruang-proyek-year">{{ p.year }}</span>            </div>          </article>        </div>      </div>    </section>    <!-- ===== SECTION 4: MATERIAL ===== -->    <section id="material" class="ruang-section" data-section>      <div class="ruang-container">        <p class="ruang-label" :style="monoStyle">Material</p>        <h2 :style="h2Style" class="ruang-h2">Material Indonesia yang kami pakai.</h2>        <p class="ruang-section-sub">Radius 300 km dari lokasi proyek. Tahan lama, mudah dirawat.</p>        <div class="ruang-material-grid" data-reveal="stagger-children">          <article            v-for="m in materials"            :key="m.name"            class="ruang-material-card"            :style="{ borderColor: borderCss }"          >            <div class="ruang-material-swatch" :style="{ background: m.color }" />            <div class="ruang-material-info">              <span class="ruang-material-cat" :style="monoStyle">{{ m.category }}</span>              <h3 class="ruang-material-name">{{ m.name }}</h3>              <p class="ruang-material-origin" :style="monoStyle">{{ m.origin }}</p>              <p class="ruang-material-desc">{{ m.desc }}</p>            </div>          </article>        </div>        <!-- Sample Box -->        <div class="ruang-sample-box" :style="{ background: surfaceElevatedCss, borderColor: borderCss }">          <div>            <h3 class="ruang-sample-title">Pesan Kotak Sampel</h3>            <p class="ruang-sample-desc">6 sampel material (5 &times; 5 cm) langsung ke alamat. Pegang dan rasakan sebelum memutuskan.</p>          </div>          <button            class="ruang-btn ruang-btn--primary"            :style="{ background: accentCss, color: accentFgCss }"            @click="sampleBoxOpen = !sampleBoxOpen"          >            {{ sampleBoxOpen ? 'Tutup' : 'Pesan Sampel' }}          </button>        </div>        <Transition enter-active-class="transition-all duration-300 ease-out" leave-active-class="transition-all duration-200 ease-in" enter-from-class="opacity-0 -translate-y-2" leave-to-class="opacity-0 -translate-y-2">          <div v-if="sampleBoxOpen" class="ruang-sample-detail" :style="{ background: surfaceCss, borderColor: borderCss }">            <p class="ruang-sample-detail-text">Dikirim 3-5 hari. Isi: Jati Jepara, Linen, Palimanan, Kuningan, Keramik, Batu Alam. Gratis ongkir Jabodetabek.</p>            <a :href="waUrl" target="_blank" rel="noopener" class="ruang-btn ruang-btn--primary" :style="{ background: accentCss, color: accentFgCss }">Pesan via WhatsApp</a>          </div>        </Transition>      </div>    </section>    <!-- ===== SECTION 5: QUIZ ===== -->    <section id="kuis" class="ruang-section ruang-section--alt" :style="{ background: surfaceCss }" data-section>      <div class="ruang-container ruang-container--narrow">        <p class="ruang-label" :style="monoStyle">Kuis Gaya</p>        <h2 :style="h2Style" class="ruang-h2">Belum tahu gaya Anda?</h2>        <p class="ruang-section-sub">Jawab 5 pertanyaan. Kami beri tahu gaya yang cocok.</p>        <!-- Progress -->        <div v-if="!quizDone" class="ruang-quiz-progress">          <div            class="ruang-quiz-progress-bar"            :style="{ width: `${((quizStep + 1) / quizQuestions.length) * 100}%`, background: accentCss }"          />        </div>        <!-- Question -->        <div v-if="!quizDone" class="ruang-quiz-q">          <p class="ruang-quiz-step" :style="monoStyle">Pertanyaan {{ quizStep + 1 }} dari {{ quizQuestions.length }}</p>          <h3 class="ruang-quiz-question">{{ quizQuestions[quizStep].q }}</h3>          <div class="ruang-quiz-options">            <button              v-for="(opt, oi) in quizQuestions[quizStep].options"              :key="oi"              class="ruang-quiz-opt"              :style="{ borderColor: borderCss }"              @click="answerQuiz(oi)"            >              <span class="ruang-quiz-opt-letter" :style="monoStyle">{{ String.fromCharCode(65 + oi) }}</span>              {{ opt }}            </button>          </div>        </div>        <!-- Result -->        <Transition enter-active-class="transition-all duration-500 ease-out" enter-from-class="opacity-0 scale-95" enter-to-class="opacity-100 scale-100">          <div v-if="quizDone && quizResult" class="ruang-quiz-result">            <p class="ruang-quiz-result-label" :style="monoStyle">Gaya Anda</p>            <h3 class="ruang-quiz-result-style" :style="{ color: accentCss }">{{ quizResult.style }}</h3>            <p class="ruang-quiz-result-desc">{{ quizResult.desc }}</p>            <div class="ruang-quiz-result-actions">              <a href="#proyek" class="ruang-btn ruang-btn--primary" :style="{ background: accentCss, color: accentFgCss }">Lihat Proyek {{ quizResult.style }}</a>              <button class="ruang-btn ruang-btn--ghost" :style="{ borderColor: accentCss, color: accentCss }" @click="resetQuiz">Ulangi Kuis</button>            </div>          </div>        </Transition>      </div>    </section>    <!-- ===== SECTION 6: GALERI ===== -->    <section id="galeri" class="ruang-section" data-section>      <div class="ruang-container">        <p class="ruang-label" :style="monoStyle">Galeri</p>        <h2 :style="h2Style" class="ruang-h2">Potongan dari ruangan yang sudah hidup.</h2>        <div class="ruang-galeri-grid" data-reveal="stagger-children">          <button            v-for="(g, i) in galeri"            :key="g.label"            class="ruang-galeri-item"            @click="lightboxIndex = i; lightboxOpen = true"          >            <div              class="ruang-galeri-img"              :style="{                background: `linear-gradient(${g.angle}deg, ${accentSoftCss}, ${mutedCss}, ${surfaceCss})`,              }"            >              <span class="ruang-galeri-img-label" :style="monoStyle">{{ g.label }}</span>            </div>          </button>        </div>      </div>    </section>    <!-- Lightbox -->    <TmplLightbox      :images="galeri.map(g => ({ src: '', alt: g.label, caption: g.label }))"      :open-index="lightboxOpen ? lightboxIndex : -1"      @close="lightboxOpen = false"    />    <!-- ===== SECTION 7: KONTAK ===== -->    <section id="kontak" class="ruang-section ruang-section--alt" :style="{ background: surfaceCss }" data-section>      <div class="ruang-container">        <div class="ruang-kontak-grid" data-reveal="stagger-children">          <div class="ruang-kontak-info">            <p class="ruang-label" :style="monoStyle">Kontak</p>            <h2 :style="h2Style" class="ruang-h2">Mulai proyek Anda.</h2>            <p class="ruang-kontak-sub">Balas dalam 48 jam. Konsultasi pertama 60 menit, gratis.</p>            <div class="ruang-kontak-detail">              <div>                <span class="ruang-kontak-detail-label" :style="monoStyle">Studio</span>                <p>Jl. Cipete Raya No. 88, Jakarta Selatan 12410</p>                <p>Buka dengan janji temu &middot; Senin-Sabtu 10.00-19.00</p>              </div>              <div>                <span class="ruang-kontak-detail-label" :style="monoStyle">WhatsApp</span>                <p>+62 851-8862-7365</p>              </div>              <div>                <span class="ruang-kontak-detail-label" :style="monoStyle">Email</span>                <p>halo@ruangstudio.id</p>              </div>            </div>            <a :href="waUrl" target="_blank" rel="noopener" class="ruang-btn ruang-btn--primary ruang-kontak-wa" :style="{ background: accentCss, color: accentFgCss }">              <svg class="w-4 h-4" fill="currentColor" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.521.149-.174.198-.298.298-.497.099-.198.05-.372-.025-.521-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.501-.669-.51l-.57-.01c-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.626.712.227 1.36.195 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413z"/></svg>              Chat WhatsApp            </a>          </div>          <div class="ruang-kontak-form-wrap" :style="{ background: surfaceElevatedCss, borderColor: borderCss }">            <TmplForm              :fields="[                { key: 'nama', label: 'Nama', type: 'text', placeholder: 'Nama lengkap', required: true },                { key: 'email', label: 'Email', type: 'email', placeholder: 'email@contoh.com', required: true },                { key: 'wa', label: 'WhatsApp', type: 'tel', placeholder: '+62 8xx-xxxx-xxxx', required: true },                { key: 'tipe', label: 'Tipe Ruangan', type: 'select', options: ['Apartemen', 'Rumah', 'Kantor', 'Kafe / Restoran', 'Lainnya'], required: true },                { key: 'luas', label: 'Luas (m\u00B2)', type: 'text', placeholder: 'contoh: 45' },                { key: 'lokasi', label: 'Lokasi', type: 'text', placeholder: 'contoh: Kemang, Jakarta Selatan' },                { key: 'gaya', label: 'Gaya yang Diminati', type: 'select', options: ['Minimalis', 'Skandinavia', 'Industrial', 'Boho', 'Klasik', 'Belum tahu'] },                { key: 'pesan', label: 'Pesan', type: 'textarea', placeholder: 'Ceritakan ruangan Anda...' },              ]"              submit-label="Kirim Pesan"              :accent="accentCss"              whatsapp-message-prefix="Halo Ruang Studio, saya ingin konsultasi desain interior."            />          </div>        </div>      </div>    </section>    <!-- ===== SECTION 8: FOOTER ===== -->    <TmplFooter data-reveal="fade-up" brand-name="Ruang Studio"      variant="columns"      :accent="accentCss"      :bg="fgCss"      :text="bgCss"      signature="Ruang yang bercerita. Interior untuk apartemen, rumah, dan ruang kerja."      :links="[        { label: 'Layanan', href: '#layanan' },        { label: 'Proyek', href: '#proyek' },        { label: 'Material', href: '#material' },        { label: 'Kuis Gaya', href: '#kuis' },        { label: 'Galeri', href: '#galeri' },        { label: 'Kontak', href: '#kontak' },      ]"    />    <!-- ===== WHATSAPP FAB ===== -->    <TmplWhatsAppFab      :template-name="tpl.brand"      template-category="architecture"    />  </div></template><style>/* ===== RUANG STUDIO GLOBAL ===== */.ruang-container {  max-width: 1200px;  margin: 0 auto;  padding: 0 1.25rem;}@media (min-width: 768px) {  .ruang-container { padding: 0 2.5rem; }}.ruang-container--narrow {  max-width: 720px;}.ruang-section {  padding: 5rem 0;}@media (min-width: 768px) {  .ruang-section { padding: 7.5rem 0; }}.ruang-label {  font-size: 11px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.6;  margin-bottom: 1rem;}.ruang-h2 {  margin-bottom: 1.25rem;  text-wrap: balance;}.ruang-section-sub {  max-width: 560px;  opacity: 0.7;  margin-bottom: 2.5rem;  line-height: 1.6;}/* ===== BUTTONS ===== */.ruang-btn {  display: inline-flex;  align-items: center;  gap: 0.5rem;  padding: 0.75rem 1.5rem;  border-radius: 8px;  font-size: 14px;  font-weight: 600;  text-decoration: none;  transition: all 200ms ease;  border: 1px solid transparent;  cursor: pointer;  font-family: inherit;}.ruang-btn--primary:hover {  opacity: 0.88;  transform: translateY(-1px);}.ruang-btn--ghost {  background: transparent;  border-width: 1px;}.ruang-btn--ghost:hover {  background: var(--ruang-accent-soft, rgba(0,0,0,0.04));}/* ===== HERO ===== */.ruang-hero {  min-height: 100vh;  display: flex;  flex-direction: column;  justify-content: center;  padding: 6rem 1.25rem 5rem;}@media (min-width: 768px) {  .ruang-hero {    padding: 8rem 2.5rem 5rem;  }}.ruang-hero__inner {  max-width: 1200px;  margin: 0 auto;  width: 100%;  display: grid;  grid-template-columns: 1fr;  gap: 3rem;  align-items: center;}@media (min-width: 1024px) {  .ruang-hero__inner {    grid-template-columns: 1.2fr 1fr;  }}.ruang-hero__label {  font-size: 11px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.6;  margin-bottom: 1.25rem;}.ruang-hero__title {  margin-bottom: 1.5rem;}.ruang-hero__sub {  max-width: 480px;  opacity: 0.7;  line-height: 1.65;  margin-bottom: 2rem;}.ruang-hero__ctas {  display: flex;  flex-wrap: wrap;  gap: 0.75rem;}.ruang-hero__scroll {  text-align: center;  margin-top: 2rem;  font-size: 10px;  letter-spacing: 0.3em;  text-transform: uppercase;  opacity: 0.4;  animation: ruang-scroll-bounce 2s ease-in-out infinite;}@keyframes ruang-scroll-bounce {  0%, 100% { transform: translateY(0); }  50% { transform: translateY(4px); }}/* 3D Sphere placeholder */.ruang-hero__sphere-wrap {  display: flex;  justify-content: center;  align-items: center;}.ruang-hero__sphere {  position: relative;  width: 260px;  height: 260px;  border-radius: 50%;  background: radial-gradient(circle at 40% 35%, var(--ruang-accent-soft, #f5ebe0), var(--ruang-accent, #b47a5c) 120%);  display: flex;  align-items: center;  justify-content: center;  animation: ruang-sphere-rotate 20s linear infinite;}@media (min-width: 768px) {  .ruang-hero__sphere { width: 360px; height: 360px; }}@keyframes ruang-sphere-rotate {  from { transform: rotate(0deg); }  to { transform: rotate(360deg); }}.ruang-hero__sphere-petal {  position: absolute;  width: 48px;  height: 48px;  border-radius: 8px;  top: 50%;  left: 50%;  margin: -24px 0 0 -24px;  opacity: 0.85;  box-shadow: 0 2px 8px rgba(0,0,0,0.1);  animation: ruang-petal-float 4s ease-in-out infinite alternate;}@keyframes ruang-petal-float {  0% { opacity: 0.85; }  100% { opacity: 1; }}.ruang-hero__sphere-label {  position: absolute;  bottom: -2rem;  font-size: 10px;  letter-spacing: 0.15em;  text-transform: uppercase;  opacity: 0.5;  animation: none;  transform: rotate(0deg);}@media (prefers-reduced-motion: reduce) {  .ruang-hero__sphere { animation: none; }  .ruang-hero__scroll { animation: none; }}/* ===== LAYANAN ===== */.ruang-layanan-grid {  display: grid;  grid-template-columns: 1fr;  gap: 1rem;}@media (min-width: 640px) {  .ruang-layanan-grid { grid-template-columns: repeat(2, 1fr); }}@media (min-width: 1024px) {  .ruang-layanan-grid { grid-template-columns: repeat(4, 1fr); }}.ruang-layanan-card {  padding: 1.5rem;  border: 1px solid;  border-radius: 8px;  transition: all 300ms cubic-bezier(0.65, 0, 0.35, 1);  position: relative;}.ruang-layanan-card:hover {  transform: translateY(-4px);  box-shadow: 0 8px 32px rgba(0,0,0,0.06);}.ruang-layanan-icon {  display: inline-flex;  align-items: center;  justify-content: center;  width: 40px;  height: 40px;  border-radius: 8px;  margin-bottom: 1rem;}.ruang-layanan-num {  display: block;  font-size: 11px;  opacity: 0.4;  margin-bottom: 0.5rem;}.ruang-layanan-title {  font-size: 17px;  font-weight: 600;  margin-bottom: 0.5rem;}.ruang-layanan-desc {  font-size: 14px;  opacity: 0.65;  line-height: 1.55;}/* ===== PROYEK ===== */.ruang-proyek-grid {  display: grid;  grid-template-columns: 1fr;  gap: 2rem;}@media (min-width: 768px) {  .ruang-proyek-grid { grid-template-columns: repeat(2, 1fr); }}@media (min-width: 1024px) {  .ruang-proyek-grid {    grid-template-columns: repeat(12, 1fr);  }  .ruang-proyek-grid > :nth-child(1),  .ruang-proyek-grid > :nth-child(4) { grid-column: span 7; }  .ruang-proyek-grid > :nth-child(2),  .ruang-proyek-grid > :nth-child(5) { grid-column: span 5; }  .ruang-proyek-grid > :nth-child(3),  .ruang-proyek-grid > :nth-child(6) { grid-column: span 12; }}.ruang-proyek-card {  border-radius: 8px;  overflow: hidden;  transition: all 300ms cubic-bezier(0.65, 0, 0.35, 1);  cursor: pointer;}.ruang-proyek-card:hover {  transform: translateY(-4px);  box-shadow: 0 12px 40px rgba(0,0,0,0.08);}.ruang-proyek-card:hover .ruang-proyek-img {  transform: scale(1.03);}.ruang-proyek-img {  aspect-ratio: 4/3;  display: flex;  align-items: center;  justify-content: center;  transition: transform 600ms cubic-bezier(0.65, 0, 0.35, 1);}.ruang-proyek-img-label {  font-size: 9px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.3;}.ruang-proyek-info {  padding: 1.25rem 0.25rem;}.ruang-proyek-meta {  display: flex;  align-items: center;  gap: 0.75rem;  margin-bottom: 0.5rem;}.ruang-proyek-tag {  font-size: 11px;  font-weight: 600;  padding: 0.2rem 0.6rem;  border-radius: 8px;}.ruang-proyek-loc {  font-size: 11px;  opacity: 0.5;}.ruang-proyek-name {  font-size: 18px;  font-weight: 600;  margin-bottom: 0.5rem;}.ruang-proyek-desc {  font-size: 13px;  opacity: 0.6;  line-height: 1.55;  margin-bottom: 0.75rem;}.ruang-proyek-year {  font-size: 11px;  opacity: 0.4;}/* ===== MATERIAL ===== */.ruang-material-grid {  display: grid;  grid-template-columns: 1fr;  gap: 1rem;}@media (min-width: 640px) {  .ruang-material-grid { grid-template-columns: repeat(2, 1fr); }}@media (min-width: 1024px) {  .ruang-material-grid {    grid-template-columns: repeat(12, 1fr);  }  .ruang-material-grid > * { grid-column: span 4; }  .ruang-material-grid > :nth-child(1) { grid-column: span 5; }  .ruang-material-grid > :nth-child(2) { grid-column: span 7; }}.ruang-material-card {  display: flex;  gap: 1rem;  padding: 1.25rem;  border: 1px solid;  border-radius: 8px;  transition: all 300ms cubic-bezier(0.65, 0, 0.35, 1);}.ruang-material-card:hover {  transform: translateY(-2px);  box-shadow: 0 6px 24px rgba(0,0,0,0.06);}.ruang-material-swatch {  width: 56px;  height: 56px;  border-radius: 8px;  flex-shrink: 0;}.ruang-material-info {  flex: 1;  min-width: 0;}.ruang-material-cat {  font-size: 10px;  letter-spacing: 0.15em;  text-transform: uppercase;  opacity: 0.5;}.ruang-material-name {  font-size: 16px;  font-weight: 600;  margin: 0.15rem 0 0.25rem;}.ruang-material-origin {  font-size: 11px;  opacity: 0.45;  margin-bottom: 0.35rem;}.ruang-material-desc {  font-size: 13px;  opacity: 0.6;  line-height: 1.5;}/* Sample Box */.ruang-sample-box {  margin-top: 2.5rem;  padding: 1.5rem;  border: 1px solid;  border-radius: 8px;  display: flex;  align-items: center;  justify-content: space-between;  gap: 1.5rem;  flex-wrap: wrap;}.ruang-sample-title {  font-size: 17px;  font-weight: 600;  margin-bottom: 0.35rem;}.ruang-sample-desc {  font-size: 14px;  opacity: 0.65;  max-width: 480px;}.ruang-sample-detail {  margin-top: 1rem;  padding: 1.5rem;  border: 1px solid;  border-radius: 8px;  display: flex;  align-items: center;  gap: 1.5rem;  flex-wrap: wrap;}.ruang-sample-detail-text {  font-size: 14px;  opacity: 0.7;  flex: 1;  min-width: 240px;}/* ===== QUIZ ===== */.ruang-quiz-progress {  height: 3px;  background: rgba(0,0,0,0.06);  border-radius: 8px;  margin-bottom: 2rem;  overflow: hidden;}.ruang-quiz-progress-bar {  height: 100%;  border-radius: 8px;  transition: width 400ms cubic-bezier(0.16, 1, 0.3, 1);}.ruang-quiz-q {  margin-bottom: 1.5rem;}.ruang-quiz-step {  font-size: 11px;  letter-spacing: 0.15em;  text-transform: uppercase;  opacity: 0.5;  margin-bottom: 0.75rem;}.ruang-quiz-question {  font-family: var(--tmpl-font-display, 'Fraunces', Georgia, serif);  font-size: clamp(1.25rem, 2.5vw, 1.5rem);  font-weight: 400;  font-style: italic;  line-height: 1.35;  margin-bottom: 1.5rem;}.ruang-quiz-options {  display: grid;  grid-template-columns: 1fr;  gap: 0.75rem;}@media (min-width: 640px) {  .ruang-quiz-options { grid-template-columns: repeat(2, 1fr); }}.ruang-quiz-opt {  display: flex;  align-items: center;  gap: 0.75rem;  padding: 1rem 1.25rem;  border: 1px solid;  border-radius: 8px;  background: transparent;  cursor: pointer;  font: inherit;  font-size: 14px;  color: inherit;  transition: all 200ms ease;  text-align: left;}.ruang-quiz-opt:hover {  border-color: var(--ruang-accent, #b47a5c);  background: var(--ruang-accent-soft, rgba(180,122,92,0.08));}.ruang-quiz-opt-letter {  display: inline-flex;  align-items: center;  justify-content: center;  width: 28px;  height: 28px;  border-radius: 8px;  font-size: 12px;  font-weight: 600;  background: rgba(0,0,0,0.04);  flex-shrink: 0;}/* Quiz Result */.ruang-quiz-result {  text-align: center;  padding: 2rem 0;}.ruang-quiz-result-label {  font-size: 11px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.5;  margin-bottom: 0.75rem;}.ruang-quiz-result-style {  font-family: var(--tmpl-font-display, 'Fraunces', Georgia, serif);  font-size: clamp(2rem, 5vw, 3rem);  font-weight: 400;  font-style: italic;  margin-bottom: 1rem;}.ruang-quiz-result-desc {  max-width: 400px;  margin: 0 auto 2rem;  opacity: 0.7;  line-height: 1.6;}.ruang-quiz-result-actions {  display: flex;  justify-content: center;  flex-wrap: wrap;  gap: 0.75rem;}/* ===== GALERI ===== */.ruang-galeri-grid {  display: grid;  grid-template-columns: repeat(2, 1fr);  gap: 0.75rem;}@media (min-width: 640px) {  .ruang-galeri-grid { grid-template-columns: repeat(3, 1fr); }}@media (min-width: 1024px) {  .ruang-galeri-grid { grid-template-columns: repeat(4, 1fr); }}.ruang-galeri-item {  background: none;  border: none;  padding: 0;  cursor: pointer;  font: inherit;}.ruang-galeri-img {  aspect-ratio: 4/3;  border-radius: 8px;  display: flex;  align-items: center;  justify-content: center;  transition: all 400ms cubic-bezier(0.65, 0, 0.35, 1);}.ruang-galeri-item:hover .ruang-galeri-img {  transform: scale(1.03);  box-shadow: 0 8px 32px rgba(0,0,0,0.08);}.ruang-galeri-img-label {  font-size: 9px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.3;}/* ===== KONTAK ===== */.ruang-kontak-grid {  display: grid;  grid-template-columns: 1fr;  gap: 2.5rem;}@media (min-width: 768px) {  .ruang-kontak-grid { grid-template-columns: 5fr 7fr; }}.ruang-kontak-sub {  opacity: 0.65;  line-height: 1.6;  margin-bottom: 2rem;  max-width: 400px;}.ruang-kontak-detail {  display: flex;  flex-direction: column;  gap: 1.25rem;  margin-bottom: 2rem;}.ruang-kontak-detail-label {  font-size: 10px;  letter-spacing: 0.2em;  text-transform: uppercase;  opacity: 0.5;  margin-bottom: 0.25rem;  display: block;}.ruang-kontak-detail p {  font-size: 14px;  opacity: 0.7;  line-height: 1.5;}.ruang-kontak-wa {  display: inline-flex;}.ruang-kontak-form-wrap {  padding: 1.5rem;  border: 1px solid;  border-radius: 8px;}@media (min-width: 768px) {  .ruang-kontak-form-wrap { padding: 2rem; }}</style>